// z2ui5_cci.cc.Markdown - renders Markdown from a bound ABAP string as HTML.                                                                                                                                                                                  
//                                                                                                                                                                                                                                                             
// UI5 has no Markdown control. sap.m.FormattedText is the usual stand-in, but                                                                                                                                                                                 
// it takes HTML and only a small whitelist of tags, so an app that wants a                                                                                                                                                                                    
// heading, a table and a code block ends up assembling HTML in ABAP. Markdown                                                                                                                                                                                 
// is the friendlier source format for the things ABAP actually produces here:                                                                                                                                                                                 
// long texts, release notes, help pages, and LLM answers - which come out of                                                                                                                                                                                  
// every model as Markdown already.                                                                                                                                                                                                                            
//                                                                                                                                                                                                                                                             
// Two libraries, and only the first is optional to understand: marked turns                                                                                                                                                                                   
// Markdown into HTML, DOMPurify strips anything dangerous out of the result.                                                                                                                                                                                  
// `sanitize` is on by default and should stay on for any text that did not                                                                                                                                                                                    
// come from your own developers - see the property comment.                                                                                                                                                                                                   
sap.ui.define(                                                                                                                                                                                                                                                 
  ["sap/ui/core/Control", "z2ui5_cci/cc/Util"],                                                                                                                                                                                                                
  (Control, Util) => {                                                                                                                                                                                                                                         
    "use strict";                                                                                                                                                                                                                                              
                                                                                                                                                                                                                                                               
    const LIB_URL = "https://cdn.jsdelivr.net/npm/marked@12.0.2/marked.min.js";                                                                                                                                                                                
    const PURIFY_URL =                                                                                                                                                                                                                                         
      "https://cdn.jsdelivr.net/npm/dompurify@3.1.6/dist/purify.min.js";                                                                                                                                                                                       
                                                                                                                                                                                                                                                               
    // UI5's base CSS resets margins on headings and lists, so unstyled                                                                                                                                                                                        
    // Markdown renders as one undifferentiated block. This is the minimum that                                                                                                                                                                                
    // makes it read like a document again - deliberately expressed in UI5                                                                                                                                                                                     
    // theme parameters, so it follows a theme switch instead of hardcoding                                                                                                                                                                                    
    // Quartz' colours. Injected once per page, not per control.                                                                                                                                                                                               
    const STYLE_ID = "z2ui5_cci-markdown-style";                                                                                                                                                                                                               
    const STYLE = `                                                                                                                                                                                                                                            
.z2ui5_cciMarkdown { line-height: 1.5; }                                                                                                                                                                                                                       
.z2ui5_cciMarkdown > *:first-child { margin-top: 0; }                                                                                                                                                                                                          
.z2ui5_cciMarkdown > *:last-child { margin-bottom: 0; }                                                                                                                                                                                                        
.z2ui5_cciMarkdown h1, .z2ui5_cciMarkdown h2, .z2ui5_cciMarkdown h3,                                                                                                                                                                                           
.z2ui5_cciMarkdown h4, .z2ui5_cciMarkdown h5, .z2ui5_cciMarkdown h6 {                                                                                                                                                                                          
  margin: 1.2em 0 0.5em; font-weight: bold; line-height: 1.25;                                                                                                                                                                                                 
}                                                                                                                                                                                                                                                              
.z2ui5_cciMarkdown h1 { font-size: 1.6em; }                                                                                                                                                                                                                    
.z2ui5_cciMarkdown h2 { font-size: 1.35em; }                                                                                                                                                                                                                   
.z2ui5_cciMarkdown h3 { font-size: 1.15em; }                                                                                                                                                                                                                   
.z2ui5_cciMarkdown p, .z2ui5_cciMarkdown ul, .z2ui5_cciMarkdown ol,                                                                                                                                                                                            
.z2ui5_cciMarkdown blockquote, .z2ui5_cciMarkdown pre, .z2ui5_cciMarkdown table {                                                                                                                                                                              
  margin: 0 0 1em;                                                                                                                                                                                                                                             
}                                                                                                                                                                                                                                                              
.z2ui5_cciMarkdown ul, .z2ui5_cciMarkdown ol { padding-inline-start: 1.6em; }                                                                                                                                                                                  
.z2ui5_cciMarkdown li { margin: 0.25em 0; }                                                                                                                                                                                                                    
.z2ui5_cciMarkdown code {                                                                                                                                                                                                                                      
  font-family: monospace; font-size: 0.9em; padding: 0.1em 0.3em;                                                                                                                                                                                              
  border-radius: 0.25em;                                                                                                                                                                                                                                       
  background: var(--sapList_Background, rgba(127, 127, 127, 0.12));                                                                                                                                                                                            
}                                                                                                                                                                                                                                                              
.z2ui5_cciMarkdown pre {                                                                                                                                                                                                                                       
  padding: 0.75em; overflow: auto; border-radius: 0.25em;                                                                                                                                                                                                      
  background: var(--sapList_Background, rgba(127, 127, 127, 0.12));                                                                                                                                                                                            
}                                                                                                                                                                                                                                                              
.z2ui5_cciMarkdown pre code { padding: 0; background: none; }                                                                                                                                                                                                  
.z2ui5_cciMarkdown blockquote {                                                                                                                                                                                                                                
  padding: 0.25em 1em; opacity: 0.85;                                                                                                                                                                                                                          
  border-inline-start: 0.25em solid var(--sapNeutralBorderColor, #999);                                                                                                                                                                                        
}                                                                                                                                                                                                                                                              
.z2ui5_cciMarkdown table { border-collapse: collapse; }                                                                                                                                                                                                        
.z2ui5_cciMarkdown th, .z2ui5_cciMarkdown td {                                                                                                                                                                                                                 
  padding: 0.35em 0.75em; text-align: start;                                                                                                                                                                                                                   
  border: 1px solid var(--sapList_BorderColor, rgba(127, 127, 127, 0.4));                                                                                                                                                                                      
}                                                                                                                                                                                                                                                              
.z2ui5_cciMarkdown th { background: var(--sapList_HeaderBackground, transparent); }                                                                                                                                                                            
.z2ui5_cciMarkdown a { color: var(--sapLinkColor, #0070f2); }                                                                                                                                                                                                  
.z2ui5_cciMarkdown img { max-width: 100%; }                                                                                                                                                                                                                    
.z2ui5_cciMarkdown hr {                                                                                                                                                                                                                                        
  border: none; margin: 1.5em 0;                                                                                                                                                                                                                               
  border-top: 1px solid var(--sapList_BorderColor, rgba(127, 127, 127, 0.4));                                                                                                                                                                                  
}                                                                                                                                                                                                                                                              
`;                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                               
    function injectStyle() {                                                                                                                                                                                                                                   
      if (document.getElementById(STYLE_ID)) return;                                                                                                                                                                                                           
      const tag = document.createElement("style");                                                                                                                                                                                                             
      tag.id = STYLE_ID;                                                                                                                                                                                                                                       
      tag.textContent = STYLE;                                                                                                                                                                                                                                 
      document.head.appendChild(tag);                                                                                                                                                                                                                          
    }                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
    return Control.extend("z2ui5_cci.cc.Markdown", {                                                                                                                                                                                                           
      metadata: {                                                                                                                                                                                                                                              
        properties: {                                                                                                                                                                                                                                          
          // the Markdown source - bind it to the ABAP string that carries it                                                                                                                                                                                  
          value: { type: "string", defaultValue: "" },                                                                                                                                                                                                         
          // Runs the generated HTML through DOMPurify before it reaches the                                                                                                                                                                                   
          // page. Turning this off means any <script> or onerror= in the                                                                                                                                                                                      
          // Markdown executes with your session: only ever do that for text                                                                                                                                                                                   
          // that is written by developers and stored in your own system, never                                                                                                                                                                                
          // for text a user typed or a model produced.                                                                                                                                                                                                        
          sanitize: { type: "boolean", defaultValue: true },                                                                                                                                                                                                   
          // A single newline becomes a <br>. marked defaults this to false,                                                                                                                                                                                   
          // this control to true: ABAP long texts are written with meaningful                                                                                                                                                                                 
          // line breaks, and losing them surprises everybody once.                                                                                                                                                                                            
          breaks: { type: "boolean", defaultValue: true },                                                                                                                                                                                                     
          // GitHub Flavoured Markdown - tables, strikethrough, autolinks                                                                                                                                                                                      
          gfm: { type: "boolean", defaultValue: true },                                                                                                                                                                                                        
          width: { type: "string", defaultValue: "" },                                                                                                                                                                                                         
          // set it together with an overflow policy if the text can grow past                                                                                                                                                                                 
          // the space you gave it                                                                                                                                                                                                                             
          height: { type: "string", defaultValue: "" },                                                                                                                                                                                                        
          libUrl: { type: "string", defaultValue: LIB_URL },                                                                                                                                                                                                   
          purifyUrl: { type: "string", defaultValue: PURIFY_URL },                                                                                                                                                                                             
        },                                                                                                                                                                                                                                                     
        events: {                                                                                                                                                                                                                                              
          // Fired for a link whose href starts with `#`, instead of following                                                                                                                                                                                 
          // it - the hook for `[order 4711](#order/4711)` style links that                                                                                                                                                                                    
          // navigate inside the app. Every other link opens in a new tab.                                                                                                                                                                                     
          linkPress: { parameters: { href: { type: "string" } } },                                                                                                                                                                                             
        },                                                                                                                                                                                                                                                     
      },                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                               
      init() {                                                                                                                                                                                                                                                 
        // one bound handler, so exit() can take it off again                                                                                                                                                                                                  
        this._onClick = this._handleClick.bind(this);                                                                                                                                                                                                          
        this._warned = false;                                                                                                                                                                                                                                  
      },                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                               
      _host() {                                                                                                                                                                                                                                                
        return document.getElementById(`${this.getId()}-host`);                                                                                                                                                                                                
      },                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                               
      _handleClick(event) {                                                                                                                                                                                                                                    
        // currentTarget is the host the listener sits on, so an anchor found                                                                                                                                                                                  
        // from here is always one this control rendered                                                                                                                                                                                                       
        const anchor = event.target.closest && event.target.closest("a[href]");                                                                                                                                                                                
        if (!anchor || !event.currentTarget.contains(anchor)) return;                                                                                                                                                                                          
                                                                                                                                                                                                                                                               
        // getAttribute, not .href: the DOM property resolves `#order/4711`                                                                                                                                                                                    
        // against the page URL and hands back an absolute one                                                                                                                                                                                                 
        const href = anchor.getAttribute("href") || "";                                                                                                                                                                                                        
        if (!href.startsWith("#")) return;                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        event.preventDefault();                                                                                                                                                                                                                                
        this.fireLinkPress({ href });                                                                                                                                                                                                                          
      },                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                               
      // Markdown -> HTML, with the sanitizing step the app did not turn off.                                                                                                                                                                                  
      _toHtml() {                                                                                                                                                                                                                                              
        const html = window.marked.parse(this.getValue() || "", {                                                                                                                                                                                              
          gfm: this.getGfm(),                                                                                                                                                                                                                                  
          breaks: this.getBreaks(),                                                                                                                                                                                                                            
        });                                                                                                                                                                                                                                                    
                                                                                                                                                                                                                                                               
        if (!this.getSanitize()) {                                                                                                                                                                                                                             
          if (!this._warned) {                                                                                                                                                                                                                                 
            this._warned = true;                                                                                                                                                                                                                               
            Util.logError(                                                                                                                                                                                                                                     
              `Markdown (${this.getId()}): sanitize is off - the rendered ` +                                                                                                                                                                                  
                `HTML is trusted as it stands`,                                                                                                                                                                                                                
            );                                                                                                                                                                                                                                                 
          }                                                                                                                                                                                                                                                    
          return html;                                                                                                                                                                                                                                         
        }                                                                                                                                                                                                                                                      
        return window.DOMPurify.sanitize(html);                                                                                                                                                                                                                
      },                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                               
      _render() {                                                                                                                                                                                                                                              
        const host = this._host();                                                                                                                                                                                                                             
        if (!host) return;                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                               
        try {                                                                                                                                                                                                                                                  
          host.innerHTML = this._toHtml();                                                                                                                                                                                                                     
        } catch (e) {                                                                                                                                                                                                                                          
          Util.logError("Markdown: could not render", e);                                                                                                                                                                                                      
          // the source is more use than an empty box when parsing failed                                                                                                                                                                                      
          host.textContent = this.getValue() || "";                                                                                                                                                                                                            
          return;                                                                                                                                                                                                                                              
        }                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                               
        // External links leave the app, so they must not be able to reach back                                                                                                                                                                                
        // into it through window.opener.                                                                                                                                                                                                                      
        host.querySelectorAll("a[href]").forEach((anchor) => {                                                                                                                                                                                                 
          if ((anchor.getAttribute("href") || "").startsWith("#")) return;                                                                                                                                                                                     
          anchor.setAttribute("target", "_blank");                                                                                                                                                                                                             
          anchor.setAttribute("rel", "noopener noreferrer");                                                                                                                                                                                                   
        });                                                                                                                                                                                                                                                    
      },                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                               
      onAfterRendering() {                                                                                                                                                                                                                                     
        injectStyle();                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                               
        const host = this._host();                                                                                                                                                                                                                             
        if (host) host.addEventListener("click", this._onClick);                                                                                                                                                                                               
                                                                                                                                                                                                                                                               
        // DOMPurify is only fetched when it is actually going to be used                                                                                                                                                                                      
        const libs = [                                                                                                                                                                                                                                         
          Util.loadScript(this.getLibUrl(), () => typeof window.marked !== "undefined"),                                                                                                                                                                       
        ];                                                                                                                                                                                                                                                     
        if (this.getSanitize()) {                                                                                                                                                                                                                              
          libs.push(                                                                                                                                                                                                                                           
            Util.loadScript(                                                                                                                                                                                                                                   
              this.getPurifyUrl(),                                                                                                                                                                                                                             
              () => typeof window.DOMPurify !== "undefined",                                                                                                                                                                                                   
            ),                                                                                                                                                                                                                                                 
          );                                                                                                                                                                                                                                                   
        }                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                               
        Promise.all(libs)                                                                                                                                                                                                                                      
          .then(() => {                                                                                                                                                                                                                                        
            if (Util.isDestroyed(this)) return;                                                                                                                                                                                                                
            this._render();                                                                                                                                                                                                                                    
          })                                                                                                                                                                                                                                                   
          .catch((e) => {                                                                                                                                                                                                                                      
            Util.logError("Markdown: library not available", e);                                                                                                                                                                                               
            // Falling back to the plain source rather than to nothing: the                                                                                                                                                                                    
            // text is still readable, just unformatted, which is the better                                                                                                                                                                                   
            // outcome in a system that cannot reach the CDN.                                                                                                                                                                                                  
            const target = this._host();                                                                                                                                                                                                                       
            if (target) target.textContent = this.getValue() || "";                                                                                                                                                                                            
          });                                                                                                                                                                                                                                                  
      },                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                               
      onBeforeRendering() {                                                                                                                                                                                                                                    
        const host = this._host();                                                                                                                                                                                                                             
        if (host) host.removeEventListener("click", this._onClick);                                                                                                                                                                                            
      },                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                               
      exit() {                                                                                                                                                                                                                                                 
        const host = this._host();                                                                                                                                                                                                                             
        if (host) host.removeEventListener("click", this._onClick);                                                                                                                                                                                            
      },                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                               
      renderer: {                                                                                                                                                                                                                                              
        apiVersion: 2,                                                                                                                                                                                                                                         
        render(rm, control) {                                                                                                                                                                                                                                  
          rm.openStart("div", control);                                                                                                                                                                                                                        
          rm.class("z2ui5_cciMarkdown");                                                                                                                                                                                                                       
          const width = Util.toCssSize(control.getWidth());                                                                                                                                                                                                    
          const height = Util.toCssSize(control.getHeight());                                                                                                                                                                                                  
          if (width) rm.style("width", width);                                                                                                                                                                                                                 
          if (height) {                                                                                                                                                                                                                                        
            rm.style("height", height);                                                                                                                                                                                                                        
            rm.style("overflow", "auto");                                                                                                                                                                                                                      
          }                                                                                                                                                                                                                                                    
          rm.openEnd();                                                                                                                                                                                                                                        
          // the generated HTML gets its own element, so re-rendering it does                                                                                                                                                                                  
          // not fight with what UI5 wrote on the control's own node                                                                                                                                                                                           
          rm.openStart("div", `${control.getId()}-host`);                                                                                                                                                                                                      
          rm.openEnd();                                                                                                                                                                                                                                        
          rm.close("div");                                                                                                                                                                                                                                     
          rm.close("div");                                                                                                                                                                                                                                     
        },                                                                                                                                                                                                                                                     
      },                                                                                                                                                                                                                                                       
    });                                                                                                                                                                                                                                                        
  },                                                                                                                                                                                                                                                           
);                                                                                                                                                                                                                                                             